cd /workspace && node -e "
const XLSX = require('xlsx');
const wb = XLSX.readFile('testbed/data/order_summary.xlsx');
const data = XLSX.utils.sheet_to_json(wb.Sheets['Orders']);

const totalOrders = data.length;
const confirmed = data.filter(r => r.Status === 'confirmed');
const cancelled = data.filter(r => r.Status === 'cancelled');
const totalRevenue = confirmed.reduce((s, r) => s + r['Total Paid'], 0);
const grandTotal = data.reduce((s, r) => s + r['Total Paid'], 0);

// Unique customers
const customers = [...new Set(data.map(r => r.Customer))];

// Top customers by confirmed spend
const custSpend = {};
confirmed.forEach(r => { custSpend[r.Customer] = (custSpend[r.Customer]||0) + r['Total Paid']; });
const topCust = Object.entries(custSpend).sort((a,b) => b[1]-a[1]).slice(0,5);

// Item frequency
const itemCount = {};
data.forEach(r => r.Items.split(', ').forEach(i => { itemCount[i] = (itemCount[i]||0) + 1; }));
const topItems = Object.entries(itemCount).sort((a,b) => b[1]-a[1]).slice(0,5);

console.log('Total orders:', totalOrders);
console.log('Confirmed:', confirmed.length, '| Cancelled:', cancelled.length);
console.log('Total revenue (confirmed):', totalRevenue);
console.log('Grand total (all):', grandTotal);
console.log('Unique customers:', customers.length);
console.log('Top customers:', JSON.stringify(topCust));
console.log('Top items:', JSON.stringify(topItems));
console.log('Date range:', [...new Set(data.map(r=>r.Date))].sort().join(' to '));
"
